#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn coseno_falls_monotonically_from_full_to_zero() {
        assert_eq!(SIG_COSENO[0], 32767);
        assert_eq!(SIG_COSENO[WINDOW_LEN - 1], 0);
        assert!(SIG_COSENO.windows(2).all(|w| w[0] >= w[1]));
    }

    #[test]
    fn coseno_is_complementary_about_628_not_627() {
        // cos(pi*(628-i)/628) == -cos(pi*i/628), so the exact identity
        // is w[i] + w[628-i] == 32767 -- indices summing to 628, which
        // is one PAST the last index.
        for i in 1..WINDOW_LEN {
            let s = SIG_COSENO[i] as i32 + SIG_COSENO[WINDOW_LEN - i] as i32;
            assert!((s - 32767).abs() <= 1, "i {i}: sum {s}");
        }
    }

    #[test]
    fn the_engines_index_pair_does_not_sum_to_unity() {
        // This is the load-bearing consequence. The fade-out leg uses
        // 627*j/n and the fade-in leg 627*(n-j)/n, which sum to 627 --
        // one short of the 628 the identity above needs. So the two
        // window weights do NOT add up to 32767, and a crossfade of a
        // signal with ITSELF is not the identity. That is exactly why
        // contiguous joins in the corpus still differ by a sample or
        // two, and why both legs must be reproduced separately rather
        // than one derived from the other.
        let n = 64usize;
        let mut off_by_any = 0;
        for j in 0..n {
            let a = SIG_COSENO[(WINDOW_LAST as usize * j) / n] as i32;
            let b = SIG_COSENO[(WINDOW_LAST as usize * (n - j)) / n] as i32;
            if a + b != 32767 {
                off_by_any += 1;
            }
        }
        assert!(off_by_any > 0, "the legs would then be redundant");
    }

    #[test]
    fn cos_cubo_is_steeper_and_bottoms_out_early() {
        assert_eq!(SIG_COS_CUBO[0], 32767);
        assert!(SIG_COS_CUBO.windows(2).all(|w| w[0] >= w[1]));
        let first_zero = SIG_COS_CUBO.iter().position(|&v| v == 0).unwrap();
        assert_eq!(first_zero, 533);
        assert!(first_zero < WINDOW_LEN - 1);
        // Steeper than SigCoseno everywhere past the start.
        assert!(SIG_COS_CUBO[314] < SIG_COSENO[314]);
    }
}
